# ======================================================================================================================================
# Quests (Docs/ZONE_LOWTOWNS.md section 5; QUEST_DESIGN.md): the breadcrumb from Corwin in Oakhaven, the main chain of five, eight side
# and NPC quests, the board's bounties; the Lowtowners' standing; five Chronicle pages and ten pages of the book of lore.
# ======================================================================================================================================
Z = "zone.lowtowns"
def O(type, text, target=None, count=1, zone=Z, **kw):
    o = {"type": type}
    if zone: o["zone"] = zone
    if target: o["target"] = target
    if count != 1: o["count"] = count
    o["text"] = text; o.update(kw); return o
def Q(id, title, kind, giver, turnIn, level, requires, label, summary, offer, progress, complete, steps, rewards, zone=Z, **kw):
    q = {"id": id, "title": title, "kind": kind, "giver": giver, "turnIn": turnIn, "zone": zone, "level": level}
    if requires: q["requires"] = requires
    q.update(kw)
    q.update({"canonStatus": label, "summary": summary, "offer": offer, "progress": progress, "complete": complete,
              "steps": [{"text": t, "objectives": objs} for t, objs in steps], "rewards": rewards})
    return q
