def D(id, title, text, label, kind=None):
    d = {"id": id}
    if kind: d["kind"] = kind
    d.update({"title": title, "text": text, "canonStatus": label}); return d
DOCUMENTS = [
    # Chronicle pages (the main chain's)
    D("doc.lowtowns.warrant_page", "The Warrant Page", "From the back of the toll-book at Argentis's outer gate, in Edda Holt's careful hand, copied from the paper the riders showed her:\n\nBy Seeker's warrant. No toll. Two children, from Oakhaven: a girl, Wren; a boy, a soldier's son, unnamed. To be held one night at the Holding House and taken up at first light.\n\nUnder it, in the same hand, smaller: They were quiet. The boy held her hand. Up is the only word on the paper I don't understand.",
      "GAME-ONLY (Wren and the soldier's boy: peaks.json, ashrim.json); Seekers' warrants CANON-EXPANDED (the Seekers are CANON, world_bible.md)"),
    D("doc.lowtowns.sparked", "What Old Wulf Saw", "Old Wulf's word, as he gave it on the steps of the soup-hall:\n\nSparked children. A light in the hands, a shimmer round the head. The Lowtowns have always had them, one or two a year. Twenty years in the militia I watched them taken out of the alleys and the gutters, a paper each time, a carriage each time. They don't come back down.\n\nWhere do they go? Up. Past the Low Stair, past the Crown. Nobody I ever knew went far enough up to see.",
      "CANON: sparked children taken from the dirty alleys and the gutters (book1 ch.13:143); Wulf and his words GAME-ONLY"),
    D("doc.lowtowns.salt_and_steel", "Salt and Steel", "Tibb Marrow's rhyme, as she sold it with every twist:\n\nSteel goes through and steel goes black,\nBone goes in and holds it back,\nSalt goes on and turns it white,\nAnd that's a drain that's shut tonight.\n\nUnder it, Old Wulf's addition: And mind the big one.",
      "CANON: steel turned black and brittle, bone harpoons, salt against Weave-Eaters (book1 ch.20:155-203); the rhyme GAME-ONLY"),
    D("doc.lowtowns.what_a_shard_is", "What a Shard Is", "Osric Fenn, at the racks, when you asked him straight:\n\nThe foundries up top make their fire from something. What's left goes down the Outfall as slag, and in the slag there are bits that glow. We sift them out. They're memory, friend. Somebody's. A face, a song, a morning. The poor buy them back to burn, a night's light at a time, and some of them buy back their own.\n\nBurn one wrong and what's left walks about grey. That's the cellar. Don't go in the cellar.",
      "GAME-ONLY reading (the shards as memory from the slag: the Sludge-Tunnels' design, DUNGEON_DESIGN.md); spent shards burned for light CANON (book1 ch.3:133-137)"),
    D("doc.lowtowns.brannoc_ledger", "Knuckle Brannoc's Ledger", "Pages from the Iron Teeth's yard ledger, greasy at the corners:\n\nShard in by the Outfall, weighed. Sifters paid by the weight. Weights sent down to the Tally, below, every seventh night, and a cut sent up the hill.\n\nOne line in another hand, not Brannoc's: The children from the Holding House are none of ours. They went up, not down. Leave it.\n\nThe last page: a map of the Outfall's first turn, and a door marked T.",
      "CANON faction (the Iron Teeth: B1WB:26); the ledger, the Tally and the hand-on to the Sludge-Tunnels GAME-ONLY (DUNGEON_DESIGN.md)"),
    D("doc.lowtowns.seer_receipt", "A Receipt from the Antiquities", "A slip in a clerk's clean hand: Received of Grimbold, factor, for the Antiquities: one parcel, delivered by a stranger, unopened. Paid in full. The back room thanks you for not asking.\n\nThe Antiquities' mark: a closed eye.",
      "CANON: the Blind Seer's Antiquities (book1 ch.3:13); the receipt GAME-ONLY. The back room is not entered."),
    # Pages of the book of lore (each at a hidden find)
    D("doc.lowtowns.rule_one", "Rule One", "Chalked under the bridge, over and over, in a dozen hands:\n\nRULE ONE OF THE LOWTOWNS: IF YOU SEE A SEEKER, EXIST SOMEWHERE ELSE.\n\nUnder the oldest, rubbed nearly away: Rule Two: see Rule One.",
      "CANON: Rule One of the Lowtowns (book1 ch.1:257); the chalk GAME-ONLY", "lore"),
    D("doc.lowtowns.soup_slate", "The Soup-Hall Slate", "Ate: the Barrow lot, four. The Rook man. The Sump sisters (paid in loaves). Old Wulf (paid in sweeping). Gytha's girl, Ysa, with a second bowl for her hands, which were cold, she said, and bright.\n\nThe last line is rubbed out with a thumb. You can still read it.",
      "GAME-ONLY", "lore"),
    D("doc.lowtowns.burner_tally", "The Burners' Tally", "Fenn, Ama: three nights. Crake, Jory: one night. Sump, the old man: five nights, two shards, bought back by the daughters. A name scratched out and three nights after it, paid.\n\nAt the bottom, a rule: never sell a family its own shard twice. Osric's hand.",
      "GAME-ONLY (the shards as burned memory: the Sludge-Tunnels' reading)", "lore"),
    D("doc.lowtowns.price_board", "The Price-Board", "SKEWERED RAT: 1 copper (crossed out). 2 copper (crossed out). 2 copper, 3 if you ask.\nAETHER-SPICED WINE: half a crown the jug, don't drink the bottom.\nSALT: 2 crowns the twist. TIBB'S.\nLAMP-SHARD: ask at the yard.\nBREAD: Elga's, grey, 1 copper, when there's flour.\n\nAcross the bottom in soot: EVERYTHING DEARER.",
      "CANON: roasting skewered rat and cheap aether-spiced wine in the Rust Market (book1 ch.3:7); the board GAME-ONLY", "lore"),
    D("doc.lowtowns.old_toll", "An Old Toll-Book Page", "A page from the toll-book of the reeve before Edda Holt:\n\nBy warrant, no toll: three children from the river towns. Held a night. Taken up. By warrant, no toll: one child, from the Rows, a girl, eight. Held a night. Taken up.\n\nAnd at the bottom, in a hand that shakes: I am not writing any more of these in the book. Let them write their own.",
      "GAME-ONLY", "lore"),
    D("doc.lowtowns.drowned_docker", "A Docker's Note", "Buttoned in the apron, a note in charcoal:\n\nIf I'm not back, it took me like it took Bessa. Salt's no good if your hand shakes. Tell Rudd I'm sorry about the shift. Tell nobody else anything.",
      "CANON-EXPANDED: Weave-Eaters and salt (book1 ch.20); the docker GAME-ONLY", "lore"),
    D("doc.lowtowns.militia_roll", "The Militia Roll", "Cut into the brick by the well: the Lowtown militia, the last roll. Twenty-two names, nineteen struck through. Brede. Hale (not the watchman: his father). Sorn. Each with a stroke, each stroke cut deep.\n\nThe last name, Wulf, with no stroke, and room left after it.",
      "CANON: the former Lowtown militia (book1 ch.20:127); the roll GAME-ONLY", "lore"),
    D("doc.lowtowns.harpoon_count", "The Harpooner's Count", "A knot for every Weave-Eater pinned, the old way, on amber cloth: forty-one knots in a grandmother's hand, three in Ketta's.\n\nStitched at the end: Bone holds. Steel lies. Salt tells it the truth.",
      "CANON: bone harpoons on amber rope (book1 ch.20:177-191); the count GAME-ONLY", "lore"),
    D("doc.lowtowns.spoon_slate", "The Spoon's Slate", "OWES: the Rook man, 3 crowns 2. The warders, 11 crowns (won't pay, won't be asked). Gorm, nothing (Gorm stops fights).\n\nBROKEN CHAIRS: a column of strokes down to the frame and onto the wall beside it.",
      "CANON-EXPANDED: the Rusty Spoon (book1 ch.1:9) and Gorm Rock-Wall (book1 ch.1:21); the slate GAME-ONLY", "lore"),
    D("doc.lowtowns.warder_orders", "A Warder's Orders", "Folded in the glove, the Holding House's standing orders:\n\nA child brought by warrant is held one night and given up at first light to whoever shows the warrant's seal. The warders do not read the warrant. The warders do not ask the child's name. The warders do not ask where up is.\n\nIn pencil on the back, in a different hand: I asked.",
      "CANON-EXPANDED: the Council's hired men; Seekers' warrants (the Seekers are CANON, world_bible.md, and only spoken of here); GAME-ONLY", "lore"),
]
