# ---- the board's bounties (Bounties: three or more common postings and the rare one) ----
def B(id, title, level, summary, offer, complete, steps, rewards, rare=False, poster="lowtowns", label="GAME-ONLY bounty"):
    q = Q(id, title, "bounty", "board", "board", level, None, label, summary, offer, "", complete, steps, rewards)
    del q["progress"]; q["poster"] = poster
    if rare: q["rare"] = True
    return q
